243	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
244	     * contained in the {@code customerCode}, scanning right to left and doubling the
245	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
246	     * own fields; null when the customer code is absent.
247	     */
248	    @Transient
249	    public Integer getCheckDigit() {
250	        if (this.customerCode == null) {
251	            return null;
252	        }
253	        int sum = 0;
254	        boolean dbl = true;
255	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
256	            char c = this.customerCode.charAt(i);
257	            if (c < '0' || c > '9') {
258	                continue;
259	            }
260	            int d = c - '0';
261	            if (dbl) {
262	                d *= 2;
263	                if (d > 9) {
264	                    d -= 9;
265	                }
266	            }
267	            sum += d;
268	            dbl = !dbl;
269	        }
270	        return (10 - (sum % 10)) % 10;
271	    }
