289	        }
290	        return Math.min(level, 3);
291	    }
292	
293	    /**
294	     * Fixed city-to-region lookup table. Any city not listed derives locality
295	     * {@code "UNKNOWN"}.
296	     */
297	    private static final Map<String, String> CITY_REGION = Map.of(
298	        "Sydney", "NSW",
299	        "Melbourne", "VIC",
300	        "Brisbane", "QLD");
301	
302	    /**
